var i=`0076-kurtoskalacs`;var a=`world-0076`;var t=`HU`;var s=`eastern-europe`;var l=6;var o=94;var r={en:`Kürtőskalács`,ua:`Кюртошкалач`};var u={en:`A classic dish from Hungary, featuring whole cow milk, chicken egg, all-purpose flour, instant yeast. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Угорщина. Основні складники: цільне коров'яче молоко, куряче яйце, пшеничне борошно універсальне, інстантні дріжджі. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,420,`g`],[`whole-cow-milk`,200,`ml`],[`instant-yeast`,8,`g`],[`white-granulated-sugar`,65,`g`],[`unsalted-butter`,70,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Roll the sweet yeast dough into thin ropes and wrap around greased cylindrical oven-safe molds; press lightly to join the coils.`,ua:`Розкачайте здобне дріжджове тісто в тонкі смужки та намотайте на змащені циліндричні жаростійкі форми, злегка притискаючи витки.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[]},{en:`Brush with butter, roll in cinnamon sugar and bake while rotating the molds when possible until golden and caramelized.`,ua:`Змастіть маслом, обкачайте в цукрі з корицею й запікайте до золотистої карамелізованої скоринки, за можливості обертаючи форми.`,t:[`roasting`],m:12,i:[[`white-granulated-sugar`,135,`g`],[`ground-cinnamon`,8,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,35,`g`]]}];var d={slug:i,id:a,country:`HU`,region:s,servings:6,minutes:94,title:r,text:u,steps:g};export{t as country,d as default,a as id,o as minutes,s as region,l as servings,i as slug,g as steps,u as text,r as title};